## Why This Is Asked
This problem tests the ability to model selections of multiple disjoint subarrays with an exact count — a common dynamic programming pattern in interviews.

## Key Concepts
- **DP on prefix**: State dp[i][t] tracks the best total using the first i elements with exactly t subarrays
- **Prefix sums**: Enable O(1) calculation of any subarray sum
- **Backpointers**: Store decisions to reconstruct the chosen subarrays
- **Edge cases**: Handle when n < k or when all values are negative

## Code Example
```javascript
function maxKSubarrays(A, k) {
  const n = A.length;
  const pref = new Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) pref[i] = pref[i - 1] + A[i - 1];

  const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-Infinity));
  const prev = Array.from({ length: n + 1 }, () => Array(k + 1).fill(null));
  dp[0][0] = 0;

  for (let i = 1; i <= n; i++) {
    for (let t = 0; t <= k; t++) {
      if (dp[i - 1][t] >= dp[i][t]) {
        dp[i][t] = dp[i - 1][t];
        prev[i][t] = { skip: true };
      }
      for (let l = 1; l <= i; l++) {
        if (t > 0 && dp[l - 1][t - 1] !== -Infinity) {
          const val = dp[l - 1][t - 1] + (pref[i] - pref[l - 1]);
          if (val > dp[i][t]) {
            dp[i][t] = val;
            prev[i][t] = { skip: false, l, t: t - 1 };
          }
        }
      }
    }
  }

  const result = [];
  let i = n, t = k;
  while (i > 0 && t > 0) {
    const p = prev[i][t];
    if (p.skip) { i--; continue; }
    result.push([p.l, i]);
    i = p.l - 1; t = p.t;
  }
  return { value: dp[n][k], subarrays: result.reverse() };
}
```

## Why This Is Asked
Tests the ability to design a DP for a non-standard segment value (length times segment max) with exact-k partitioning and path reconstruction.

## Key Concepts
- 2D DP: dp[i][t] stores best value for first i elements using t segments
- Transition: dp[i][t] = max over j of dp[j][t-1] + (i-j) * max(A[j+1..i])
- On-the-fly max: as j decreases, update max(A[j+1..i]) incrementally
- Reconstruction: parent[i][t] stores last cut; backtrack to produce segments
- Complexity: O(n^2 k) time, O(nk) space

## Code Example
```javascript
function solve(A, n, k){
  const dp = Array.from({length: n+1}, ()=> Array(k+1).fill(-Infinity));
  const par = Array.from({length: n+1}, ()=> Array(k+1).fill(-1));
  dp[0][0] = 0;
  for(let i=1;i<=n;i++){
    for(let t=1;t<=Math.min(i,k);t++){
      let maxv = -Infinity;
      for(let j=i-1;j>=t-1;j--){
        maxv = Math.max(maxv, A[j]); // adjust if 0-based/1-based indexing
        const val = dp[j][t-1] + (i-j) * maxv;
        if(val > dp[i][t]){ dp[i][t] = val; par[i][t] = j; }
      }
    }
  }
  // reconstruct
  let segments = [];
  let i=n, t=k;
  while(t>0){
    const j = par[i][t];
    segments.push([j+1, i]);
    i = j; t--;
  }
  segments.reverse();
  return {value: dp[n][k], segments};
}
```

## Why This Is Asked
This problem tests dynamic programming on partitioning with a non-linear cost function (distinct character count). It's concrete, implementable, and scales well to typical interview constraints.

## Key Concepts
- DP over prefixes and partition count
- Precomputing distinct character counts for all substrings (O(n²) with two pointers)
- Reconstruction via parent pointers
- Time/space trade-offs

## Code Example
```javascript
function maxPartitionDistinct(s, k) {
  const n = s.length;
  const dist = Array.from({ length: n }, () => Array(n).fill(0));

  for (let i = 0; i < n; i++) {
    const seen = new Set();
    for (let j = i; j < n; j++) {
      seen.add(s[j]);
      dist[i][j] = seen.size;
    }
  }

  const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-Infinity));
  const prev = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-1));
  dp[0][0] = 0;

  for (let i = 1; i <= n; i++) {
    for (let t = 1; t <= Math.min(i, k); t++) {
      for (let j = t - 1; j < i; j++) {
        const val = dp[j][t - 1] + dist[j][i - 1];
        if (val > dp[i][t]) {
          dp[i][t] = val;
          prev[i][t] = j;
        }
      }
    }
  }

  const partitions = [];
  let [i, t] = [n, k];
  while (t > 0) {
    const j = prev[i][t];
    partitions.unshift([j, i - 1]);
    i = j;
    t--;
  }

  return { value: dp[n][k], partitions };
}
```

## Why This Is Asked
- Tests DP state design that tracks both position and budget (flips).
- Requires reconstruction to return exact indices, not just value.

## Key Concepts
- DP state with dual dimension (i, flips)
- Transition depends on current bit; reconstruction via predecessor pointers
- Time/space trade-offs

## Code Example
```javascript
function maxOnesRun(s, k) {
  const n = s.length;
  const dp = Array.from({length: n}, () => Array(k+1).fill(0));
  const prev = Array.from({length: n}, () => Array.from({length: k+1}, () => null));
  let bestLen = 0, bestEnd = 0, bestJ = 0;
  for (let i=0; i<n; i++) {
    for (let j=0; j<=k; j++) {
      if (s[i] === '1') {
        dp[i][j] = (i>0 ? dp[i-1][j] : 0) + 1;
        prev[i][j] = i>0 ? [i-1, j] : null;
      } else if (j>0) {
        dp[i][j] = (i>0 ? dp[i-1][j-1] : 0) + 1;
        prev[i][j] = i>0 ? [i-1, j-1] : null;
      } else {
        dp[i][j] = 0; prev[i][j] = null;
      }
      if (dp[i][j] > bestLen) { bestLen = dp[i][j]; bestEnd = i; bestJ = j; }
    }
  }
  const start = bestEnd - bestLen + 2;
  return {bestLen, start, end: bestEnd+1, flips: bestJ};
}
```

## Follow-up Questions
- How would you reduce space to O(k)?
- How would you adapt if flips must happen in blocks?

## Why This Is Asked
DP over subsequences with a fixed length captures real-world problems like quantizing sequences while minimizing total variation; it tests state definition, reconstruction, and complexity trade-offs.

## Key Concepts
- DP state: last index and length; - Transition: O(n) over prior indices; - Reconstruction via parent pointers; - Complexity: O(n^2 k) time, O(nk) space.

## Code Example
```javascript
function minCostSubsequence(A, k) {
  const n = A.length, INF = 1e18;
  const dp = Array.from({length: n}, ()=> Array(k+1).fill(INF));
  const par = Array.from({length: n}, ()=> Array(k+1).fill(-1));
  for (let i=0;i<n;i++) dp[i][1] = 0;
  for (let t=2;t<=k;t++) {
    for (let i=0;i<n;i++) {
      for (let j=0;j<i;j++) {
        const val = dp[j][t-1] + Math.abs(A[i]-A[j]);
        if (val < dp[i][t]) { dp[i][t] = val; par[i][t] = j; }
      }
    }
  }
  let best = INF, last = -1;
  for (let i=0;i<n;i++) if (dp[i][k] < best) { best = dp[i][k]; last = i; }
  const idx = Array(k);
  let t = k, cur = last;
  while (t>=1) { idx[t-1] = cur; cur = par[cur][t]; t--; }
  return {cost: best, indices: idx};
}
```

## Why This Is Asked
Tests ability to craft DP with interval constraints and reconstruction using palindromic substrings.

## Key Concepts
- Palindromic substring precomputation in O(n^2)
- DP over prefix length and exact count: dp[i][t]
- Transition considers ending a palindrome at i with start p
- Reconstruction requires backpointers to recover substrings

## Code Example
```javascript
function maxPalSubstr(s, k) {
  const n = s.length;
  const isPal = Array.from({length: n}, () => Array(n).fill(false));
  for (let i = n - 1; i >= 0; --i) {
    for (let j = i; j < n; ++j) {
      if (s[i] === s[j] && (j - i < 2 || isPal[i+1][j-1])) isPal[i][j] = true;
    }
  }
  const NEG = -1e9;
  const dp = Array.from({length: n+1}, () => Array(k+1).fill(NEG));
  const par = Array.from({length: n+1}, () => Array(k+1).fill(-1));
  dp[0][0] = 0;
  for (let i = 1; i <= n; i++) {
    for (let t = 0; t <= k; t++) {
      dp[i][t] = Math.max(dp[i][t], dp[i-1][t]);
      if (t > 0) {
        for (let p = 0; p < i; p++) {
          if (isPal[p][i-1]) {
            const val = dp[p][t-1] + (i - p);
            if (val > dp[i][t]) { dp[i][t] = val; par[i][t] = p; }
          }
        }
      }
    }
  }
  // Reconstruction would trace par[] to extract substrings
}
```

